 CHECK("default-aliases",format(LOCALE_USER_DEFAULT,0,&t,0,L"24.10.2026")&&format(LOCALE_SYSTEM_DEFAULT,0,&t,0,L"24.10.2026"));CHECK("metadata-flags",format(0x407,LOCALE_NOUSEROVERRIDE|LOCALE_USE_CP_ACP,&t,0,L"24.10.2026"));
 SetLastError(0);CHECK("custom-flag-invalid",!GetDateFormatW(0x407,DATE_SHORTDATE,&t,L"dd",b,128)&&GetLastError()==1004);SetLastError(0);CHECK("conflicting-styles",!GetDateFormatW(0x409,3,&t,0,b,128)&&GetLastError()==1004);SetLastError(0);CHECK("unsupported-calendar",!GetDateFormatW(0x409,DATE_USE_ALT_CALENDAR,&t,0,b,128)&&GetLastError()==50);SetLastError(0);CHECK("unsupported-era",!GetDateFormatW(0x409,0,&t,L"gg",b,128)&&GetLastError()==50);
 SetLastError(0);CHECK("unknown-locale",!GetDateFormatW(0x411,0,&t,0,b,128)&&GetLastError()==87);SetLastError(0);CHECK("unknown-flags",!GetDateFormatW(0x409,0x100,&t,0,b,128)&&GetLastError()==1004);SetLastError(0);CHECK("negative-capacity",!GetDateFormatW(0x409,0,&t,0,b,-1)&&GetLastError()==87);SetLastError(0);CHECK("null-positive-output",!GetDateFormatW(0x409,0,&t,0,0,30)&&GetLastError()==122);
 t.wYear=1601;t.wMonth=1;t.wDay=1;CHECK("earliest-supported-Monday",format(0x409,0,&t,L"dddd yyyy-MM-dd",L"Monday 1601-01-01"));t.wYear=9999;t.wMonth=12;t.wDay=31;CHECK("far-future-Friday",format(0x409,0,&t,L"dddd yyyy-MM-dd",L"Friday 9999-12-31"));
 int valid=1;for(unsigned year=1601;year<=2400;year++){t.wYear=year;t.wMonth=2;t.wDay=29;int leap=year%4==0&&(year%100!=0||year%400==0);SetLastError(0);int n=GetDateFormatW(0x409,0,&t,L"yyyy-MM-dd",b,128);if(leap?(!n||b[8]!='2'||b[9]!='9'):(n||GetLastError()!=87))valid=0;}CHECK("800-year-leap-boundaries",valid);
 t.wYear=2026;t.wMonth=4;t.wDay=31;SetLastError(0);CHECK("invalid-April31",!GetDateFormatW(0x409,0,&t,0,b,128)&&GetLastError()==87);t.wMonth=13;t.wDay=1;SetLastError(0);CHECK("invalid-month",!GetDateFormatW(0x409,0,&t,0,b,128)&&GetLastError()==87);t.wMonth=1;t.wYear=1600;SetLastError(0);CHECK("before-range",!GetDateFormatW(0x409,0,&t,0,b,128)&&GetLastError()==87);
 SYSTEMTIME before,after;GetLocalTime(&before);int current=GetDateFormatW(0x409,0,0,L"yyyy-MM-dd",b,128);GetLocalTime(&after);WCHAR a[40],z[40];GetDateFormatW(0x409,0,&before,L"yyyy-MM-dd",a,40);GetDateFormatW(0x409,0,&after,L"yyyy-MM-dd",z,40);CHECK("current-provider",current==11&&(eq(b,a)||eq(b,z)));
 HANDLE threads[8];for(int i=0;i<8;i++)threads[i]=CreateThread(0,0,worker,0,0,0);int ok=1;for(int i=0;i<8;i++){DWORD code=9;if(!threads[i]||WaitForSingleObject(threads[i],INFINITE)!=WAIT_OBJECT_0||!GetExitCodeThread(threads[i],&code)||code)ok=0;if(threads[i])CloseHandle(threads[i]);}CHECK("parallel-date-lasterror",ok);
